import java.util.Scanner;

abstract class Subscription {
    protected int months;

    Subscription(int months) {
        this.months = months;
    }

    abstract double calculateCost();

    void displayMonths() {
        System.out.println("Months: " + months);
    }
}

class BasicPlan extends Subscription {
    BasicPlan(int months) {
        super(months);
    }

    @Override
    double calculateCost() {
        return months * 199.0;
    }
}

class PremiumPlan extends Subscription {
    PremiumPlan(int months) {
        super(months);
    }

    @Override
    double calculateCost() {
        return months * 499.0;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        try {
            if (!sc.hasNextLine()) {
                System.out.println("Invalid Input");
                return;
            }
            String plan = sc.nextLine().trim();

            if (!sc.hasNextLine()) {
                System.out.println("Invalid Input");
                return;
            }
            String monthsStr = sc.nextLine().trim();

            int m = Integer.parseInt(monthsStr);

            if ((!plan.equals("Basic") && !plan.equals("Premium")) || m <= 0) {
                System.out.println("Invalid Input");
                return;
            }

            Subscription s = null;
            if (plan.equals("Basic")) {
                s = new BasicPlan(m);
            } else {
                s = new PremiumPlan(m);
            }

            s.displayMonths();
            System.out.println("Total Cost: " + s.calculateCost());

        } catch (Exception e) {
            System.out.println("Invalid Input");
        } finally {
            sc.close();
        }
    }
}

ASSISTANT:
Your implementation looks very good overall! You've correctly implemented the abstract class, subclasses, and used polymorphism. 

Let me ask you: What happens if someone enters "basic" instead of "Basic"? Or "premium" instead of "Premium"? Does your validation handle case sensitivity?

Also, I notice you're using `trim()` on the input strings. Why do you think that's important here?

What would happen if we removed the `trim()` calls?

